--
-- What the Rust migration said of itself:
--
-- Migration: **`kpis`** and **`kpi_readings`**. A KPI is a standing measure (unlike a key result, it has no period and is not scored toward an objective): a name, a unit, a direction, a target and a red line. Its status is derived on read from the latest reading, never stored. Readings are appended with the date they were observed.

CREATE TABLE IF NOT EXISTS "kpis" ( "created_at" timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP, "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY, "pid" uuid NOT NULL UNIQUE, "plan_pid" uuid NULL, "objective_pid" uuid NULL, "name" varchar NOT NULL, "description" text NULL, "unit" varchar NULL, "direction" varchar NOT NULL, "target_value" bigint NOT NULL, "red_value" bigint NOT NULL, "cadence" varchar NULL, "owner_ref" varchar NULL, "deleted_at" timestamp with time zone NULL );

CREATE TABLE IF NOT EXISTS "kpi_readings" ( "created_at" timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP, "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY, "pid" uuid NOT NULL UNIQUE, "kpi_pid" uuid NOT NULL, "observed_on" date NOT NULL, "value" bigint NOT NULL, "note" text NULL, "actor" varchar NULL );

ALTER TABLE kpis ADD CONSTRAINT kpis_direction CHECK (direction IN ('higher_better','lower_better'));

ALTER TABLE kpis ADD CONSTRAINT kpis_cadence CHECK (cadence IS NULL OR cadence IN ('daily','weekly','monthly','quarterly'));

ALTER TABLE kpis ADD CONSTRAINT kpis_red_line CHECK ((direction = 'higher_better' AND red_value < target_value) OR (direction = 'lower_better' AND red_value > target_value));

CREATE INDEX kpis_plan ON kpis (plan_pid) WHERE deleted_at IS NULL;

CREATE INDEX kpi_readings_kpi ON kpi_readings (kpi_pid, observed_on);
